<script lang="ts">
  import { AdminOverviewResponse, NewsletterSubscribersResponse } from '@gbfm/api/admin'
  import { SendMixNotificationResponse } from '@gbfm/api/email'
  import { Schema } from 'effect'
  import { onMount } from 'svelte'
  import { dashboardJson,jsonRequest } from '../api'
  type Overview=typeof AdminOverviewResponse.Type
  type Mix={id:string;slug:string;title:string;createdAt:string}
  let subscribers=$state<typeof NewsletterSubscribersResponse.Type.subscribers>([]),overview=$state<Overview>(),selectedId=$state(''),artistName=$state(''),testRecipient=$state(''),message=$state(''),pending=$state(false)
  let mixes=$derived((overview?.publishing.recentContent??[]).filter((item)=>item.type==='mix'&&!item.draft).slice(0,8).map((item):Mix=>({id:item.id,slug:item.slug,title:item.title??item.slug,createdAt:item.createdAt})))
  let selected=$derived(mixes.find((mix)=>mix.id===selectedId)??mixes[0])
  let active=$derived(subscribers.filter((subscriber)=>!subscriber.unsubscribedAt))
  const count=(value:number)=>new Intl.NumberFormat('en-US').format(value)
  const date=(value:string)=>new Date(value).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})
  onMount(async()=>{try{const [audience,stats]=await Promise.all([dashboardJson(NewsletterSubscribersResponse,'/api/admin/newsletter-subscribers'),dashboardJson(AdminOverviewResponse,'/api/admin/overview')]);subscribers=audience.subscribers;overview=stats}catch{message='Could not load newsletter operations.'}})
  async function send(test:boolean){if(!selected)return;if(!test&&!confirm(`Send “${selected.title}” to ${active.length} subscribers? This cannot be undone.`))return;pending=true;try{const artist=artistName.trim();const body:Schema.Json=test?(artist?{mixSlug:selected.slug,recipients:[testRecipient],metadata:{artistName:artist}}:{mixSlug:selected.slug,recipients:[testRecipient]}):(artist?{mixSlug:selected.slug,metadata:{artistName:artist}}:{mixSlug:selected.slug});const result=await dashboardJson(SendMixNotificationResponse,'/api/email/send-mix-notification',jsonRequest('POST',body));message=`${result.message} (${result.sentTo.length} recipient${result.sentTo.length===1?'':'s'})`}catch(cause){message=cause instanceof Error?cause.message:'Send failed.'}finally{pending=false}}
</script>
<div class="space-y-6"><div class="grid gap-4 md:grid-cols-2 xl:grid-cols-4">{#each [['Active subscribers',active.length,'Audience currently able to receive sends.'],['New in 30 days',overview?.community.newsletter.newLast30Days??0,'Recent list growth.'],['Unsubscribed',subscribers.length-active.length,'Audience churn.'],['Sendable mixes',mixes.length,'Recently published mixes.']] as metric}<article class="rounded border p-5"><h2 class="text-sm font-medium text-muted-foreground">{metric[0]}</h2><div class="mt-2 text-3xl font-black">{count(Number(metric[1]))}</div><p class="mt-2 text-sm text-muted-foreground">{metric[2]}</p></article>{/each}</div><section class="space-y-5 rounded border p-5"><h2 class="text-xl font-bold">Send a new mix notification</h2><p class="text-sm text-muted-foreground">Pick a recently published mix, preview the message, and test it before broadcasting.</p>{#if mixes.length===0}<p class="text-muted-foreground">No published mixes available.</p>{:else}<div class="grid gap-3 md:grid-cols-2">{#each mixes as mix}<button class={`rounded border p-4 text-left ${selected?.id===mix.id?'border-foreground bg-muted/50':'hover:bg-muted/40'}`} onclick={()=>selectedId=mix.id}><span class="text-sm text-muted-foreground">Mix · {date(mix.createdAt)}</span><strong class="mt-2 block">{mix.title}</strong><span class="text-sm text-muted-foreground">/mixes/{mix.slug}</span></button>{/each}</div>{/if}<label class="block max-w-sm text-sm">Artist name (optional)<input class="mt-1 w-full rounded border bg-background p-2" placeholder="Guide Fari" bind:value={artistName}/></label>{#if selected}<div class="rounded border bg-muted/30 p-4 text-sm"><strong>Email preview</strong><p class="mt-2"><span class="text-muted-foreground">Subject:</span> New mix: {selected.title}</p><p><span class="text-muted-foreground">Artist:</span> {artistName.trim()||'Guide Fari'}</p><p><span class="text-muted-foreground">Link:</span> /mixes/{selected.slug}</p></div>{/if}<div class="flex flex-wrap gap-2"><button class="rounded bg-foreground px-4 py-2 text-background" disabled={!selected||pending} onclick={()=>void send(false)}>{pending?'Sending…':`Send to ${count(active.length)} subscribers`}</button><input class="rounded border bg-background p-2" type="email" placeholder="Test recipient" bind:value={testRecipient}/><button class="rounded border px-4 py-2" disabled={!selected||!testRecipient||pending} onclick={()=>void send(true)}>Send test</button></div></section><section class="rounded border p-5"><h2 class="mb-4 text-xl font-bold">Audience <span class="text-sm font-normal text-muted-foreground">({subscribers.length})</span></h2><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead><tr class="border-b"><th class="p-2">Email</th><th class="p-2">Name</th><th class="p-2">Source</th><th class="p-2">Status</th><th class="p-2">Subscribed</th></tr></thead><tbody>{#each subscribers as subscriber}<tr class="border-b last:border-0"><td class="p-2">{subscriber.email}</td><td class="p-2 text-muted-foreground">{subscriber.name??'—'}</td><td class="p-2 text-muted-foreground">{subscriber.source??'—'}</td><td class="p-2"><span class={`rounded-full border px-2 py-1 text-xs ${subscriber.unsubscribedAt?'border-destructive text-destructive':''}`}>{subscriber.unsubscribedAt?'Unsubscribed':'Active'}</span></td><td class="p-2 text-muted-foreground">{date(subscriber.createdAt)}</td></tr>{/each}</tbody></table></div></section>{#if message}<p class="rounded border p-3" aria-live="polite">{message}</p>{/if}</div>
